export const CONTROL_PLANE_REQUIREMENTS = z
    .array(controlPlaneRequirementSchema)
    .parse([
    {
        id: "attachable_sessions",
        stage: "implemented",
        summary: "Multiple clients must be able to attach to one live session.",
        rationale: "Web, CLI, and desktop clients should observe the same durable session instead of spinning up incompatible one-shot transports.",
    },
    {
        id: "deterministic_replay",
        stage: "implemented",
        summary: "Reconnect must resume from a cursor and replay events in deterministic order.",
        rationale: "The UI should rebuild from events alone, with no hidden state or reconnect-specific branches.",
    },
    {
        id: "stable_persisted_event_metadata",
        stage: "implemented",
        summary: "Persisted events must carry stable metadata such as event ID and timestamp.",
        rationale: "Clients need durable cursors, deduplication keys, and time-ordering that survive reconnects and exports.",
    },
    {
        id: "explicit_client_correlation",
        stage: "implemented",
        summary: "Client-originated work must support correlation IDs such as clientMessageId or requestId.",
        rationale: "Optimistic UI and multiplexed streaming break down if requests cannot be matched to later events.",
    },
    {
        id: "event_driven_ui",
        stage: "implemented",
        summary: "User interfaces should derive visible state from protocol events, not stdout parsing or hidden client state.",
        rationale: "That keeps web and desktop behavior aligned and makes replay/debugging tractable.",
    },
    {
        id: "separate_live_stream_and_audit_log",
        stage: "implemented",
        summary: "Live session events and document audit logs are related but distinct protocols.",
        rationale: "The session control plane optimizes for attach/replay, while document audit routes optimize for workflow inspection and analytics.",
    },
    {
        id: "multi_transport_contract",
        stage: "planned",
        summary: "The same logical protocol should be able to ride over WebSocket, HTTP, and SSE surfaces.",
        rationale: "OpenCode-style attachable clients want HTTP plus SSE, while current Okra clients already rely on WebSocket replay.",
    },
    {
        id: "first_class_permissions",
        stage: "planned",
        summary: "Permission requests and replies should become explicit protocol objects and endpoints.",
        rationale: "This is required for attachable desktop/web shells and for parity with server-style harnesses such as OpenCode.",
    },
    {
        id: "cloudflare_agents_compatible_events",
        stage: "planned",
        summary: "Event shapes should project cleanly onto Cloudflare Agents and SSE-style transports.",
        rationale: "We want one logical protocol even if the runtime or transport changes between WebSocket, HTTP, SSE, and Cloudflare Agents primitives.",
    },
]);
